-- Rules of the Auto build button of the passive tree without engine calls (passive_builds.lua; tests:
-- tests/passive_builds_test.lua). The paths are in passive_builds_data.lua (generated by tools/gen_passive_builds.lua),
-- the recipes and texts in passive_builds_config.lua. Lua 5.1 / LuaJIT and Lua 5.3.
--
--   PassiveBuildsCore.list(data, cfg, statsCfg, classKey)   the descriptors of a class's builds: {id, kind, name, text,
--                                                           points, top, fit} in menu order (see there)
--   PassiveBuildsCore.find(data, classKey, id)              the build {id, kind, order, masteries, top} or nil
--   PassiveBuildsCore.summary(cfg, top, T)                  "Fire damage +52, Fire resist +35": the main stats of a build
--   PassiveBuildsCore.plan(tree, build, ctx)                what applying a build does (see there)
--
-- A build is an ORDER of node ids in which every node touches the start or an earlier node, so every prefix is a legal
-- build: a character takes as many as it has points for.

PassiveBuildsCore = PassiveBuildsCore or {}
local M = PassiveBuildsCore

-- the menu text of a build: kind "role" (Recommended) or "focus"; name / text are the English keys for Chaos.t / tr
function M.list(data, cfg, statsCfg, classKey)
	local builds = data.classes[classKey] or {}
	local info = statsCfg and PassiveStatsCore and PassiveStatsCore.classInfo(statsCfg, classKey)
	local roles, themes = {}, {}
	for _, role in ipairs(cfg.roles[classKey] or {}) do
		roles[classKey .. "_" .. role.id] = role
	end
	for _, theme in ipairs(cfg.themes) do
		themes["focus_" .. theme.key] = theme
	end
	local out = {}
	for i, b in ipairs(builds) do
		local role, theme = roles[b.id], themes[b.id]
		local entry = {id = b.id, kind = b.kind, points = #b.order, top = b.top, index = i}
		if b.kind == "role" and role then
			entry.name, entry.text = role.name, cfg.kinds[role.kind]
		elseif theme then
			entry.name, entry.text = theme.name, theme.text
		end
		-- how well the build's main stats fit the class: 2 per primary stat, 1 per secondary (statsCfg lists)
		local fit = 0
		for _, t in ipairs(b.top) do
			local tag = info and info.tag[t[1]]
			fit = fit + (tag == "primary" and 2 or (tag == "secondary" and 1 or 0))
		end
		entry.fitScore = fit
		entry.fit = fit >= 4 and "primary" or (fit >= 2 and "secondary" or nil)
		if entry.name then
			out[#out + 1] = entry
		end
	end
	-- Recommended keep the order of the config; Focus: the best fit for the class first, then the config order
	table.sort(out, function(a, b)
		if a.kind ~= b.kind then
			return a.kind == "role"
		end
		if a.kind == "focus" and a.fitScore ~= b.fitScore then
			return a.fitScore > b.fitScore
		end
		return a.index < b.index
	end)
	return out
end

function M.find(data, classKey, id)
	for _, b in ipairs(data.classes[classKey] or {}) do
		if b.id == id then
			return b
		end
	end
	return nil
end

local function number(v)
	if v == math.floor(v) then
		return string.format("%d", v)
	end
	return string.format("%.1f", v)
end

function M.summary(cfg, top, T)
	local parts = {}
	for _, t in ipairs(top or {}) do
		local label = cfg.statLabels[t[1]]
		if label then
			parts[#parts + 1] = T(label[1]) .. " +" .. number(t[2] * label[2])
		end
	end
	return table.concat(parts, ", ")
end

-- ------------------------------------------------------------------------------------------------ applying
-- plan(tree, build, ctx): what Apply (reset = false) or Reset and apply (reset = true) does.
--   ctx = {classKey, current = saved node ids, currentMasteries = {[id] = choice}, points = passive points owned,
--          reset = bool}
-- Apply only adds: the nodes of the build in its order, the ones missing, up to the free points (points minus the nodes
-- held). Reset and apply starts from nothing: the first `points` nodes of the build; whatever the character held outside
-- them is taken back (treeReset = true, the full reset price). A node of another class, an unknown one, or one that does
-- not touch the nodes taken so far is skipped with its reason ("class", "unknown", "disconnected"), the ones that do not
-- fit the points with "points".
-- Returns {ids = final allocation, added = new ids in order, kept = ids held that stay, removed = ids taken back,
--          skipped = {{id, why}}, masteries = {[id] = choice}, treeReset = bool, wanted = #build.order, changed = bool}
function M.plan(tree, build, ctx)
	local held, heldList = {}, {}
	for _, id in ipairs(ctx.current or {}) do
		if not held[id] then
			held[id] = true
			heldList[#heldList + 1] = id
		end
	end
	local points = math.max(0, math.floor(tonumber(ctx.points) or 0))
	local reset = ctx.reset == true
	local taken, order = {[tree.root] = true}, {}
	if not reset then
		for _, id in ipairs(heldList) do
			taken[id] = true
			order[#order + 1] = id
		end
	end
	local count = reset and 0 or #heldList
	local added, skipped = {}, {}
	local function touches(id)
		for _, nb in ipairs(tree.nodes[id].n) do
			if taken[nb] then
				return true
			end
		end
		return false
	end
	local function allowed(node)
		return not node.c or (ctx.classKey ~= nil and node.c[ctx.classKey] == true)
	end
	for _, id in ipairs(build.order) do
		local node = tree.nodes[id]
		if not node or id == tree.root then
			skipped[#skipped + 1] = {id = id, why = "unknown"}
		elseif taken[id] then
			-- already held (Apply): nothing to do
		elseif not allowed(node) then
			skipped[#skipped + 1] = {id = id, why = "class"}
		elseif not touches(id) then
			skipped[#skipped + 1] = {id = id, why = "disconnected"}
		elseif count >= points then
			skipped[#skipped + 1] = {id = id, why = "points"}
		else
			taken[id] = true
			order[#order + 1] = id
			count = count + 1
			if not held[id] then
				added[#added + 1] = id
			end
		end
	end
	local final = {}
	for _, id in ipairs(order) do
		final[id] = true
	end
	local kept, removed = {}, {}
	for _, id in ipairs(heldList) do
		if final[id] then
			kept[#kept + 1] = id
		else
			removed[#removed + 1] = id
		end
	end
	-- a Reset and apply that takes nothing back is the same as Apply (and free)
	local masteries = {}
	for id, choice in pairs(ctx.currentMasteries or {}) do
		if final[id] and held[id] then
			masteries[id] = choice
		end
	end
	for _, id in ipairs(added) do
		local node = tree.nodes[id]
		if type(node.m) == "table" and #node.m > 0 then
			masteries[id] = (build.masteries or {})[id] or 1
		end
	end
	return {
		ids = order, added = added, kept = kept, removed = removed, skipped = skipped, masteries = masteries,
		treeReset = #removed > 0, wanted = #build.order, changed = #added > 0 or #removed > 0
	}
end

return PassiveBuildsCore
